/* Sass source:
$colors: (primary: #3b82f6, danger: #ef4444, success: #22c55e);
@each $name, $value in $colors {
  .text-#{$name} { color: $value; }
}
*/
.text-primary { color: #3b82f6; }
.text-danger { color: #ef4444; }
